"""Build the public, synthetic-data acceptance readout from recorded execution results."""
import json,html,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[1]
r=json.loads((root/'docs/sim200/acceptance/result.json').read_text(encoding='utf8'))
road=json.loads((root/'docs/sim200/roads/road-integration.json').read_text(encoding='utf8'))
opt=json.loads((root/'docs/verification/v13/optimizer-live/summary.json').read_text(encoding='utf8'))
e=html.escape
cards=[('200','唯一主订单'),('180','运输交付并结算'),('12','自提完成核账'),('8','取消并释放库存'),('252','首次交接唯一设备'),('20','原机返修回送关闭')]
rows=[('导入及重复导入','实际销售 CSV preview / confirm / handoff；重复导入不增加主单'),('库存守恒',f"初始 {r['initial_stock_units']} + 海运接收 {r['ocean_receipt_units']} = 260；最终交付 252 + 可用 8"),('过程证据',f"{r['trace_events']:,} 条逐步记录；{r['expected_rejections']} 次预期拒绝；包含岗位、版本、业务时钟及真实执行时间"),('售后','20 个原 SN 回收、维修、原机回送、验收及费用关闭'),('财务',f"主单 USD {r['main_actual_cost']:,.2f}；关联返修回送 USD {r['repair_actual_cost']:,.2f}"),('最终异常',f"取消 SN 锁 {r['cancelled_sn_locks']}；孤立预订 {r['orphan_bookings']}；开放售后 {r['open_aftercare']}"),('真实道路','DFW、Houston、Los Angeles、Atlanta 小范围图；200订单与8仓站道路匹配；3,659对方向时距及回程、双车排程'),('原生优化','Valhalla / VROOM / OR-Tools CP-SAT：6票、2日期、多车，60候选中24个可行，6/6覆盖；已验证候选集合内最优'),('页面一致性','独立SIM200库、地图/日期同计划；日期筛选保留200票计算范围；本机后台任务可取消和恢复')]
rows.extend([('补充关键场景','同址授权送收峰值、跨票 F04 原子签发、故障两站后冻结前缀救援、旧数据备份迁移回滚、进程中断后租约恢复均有专项证据'),('快速试用','进入地图后点击“新建 6 票试排”，比较方案、查看地图/时间轴并采用草案；正式签发继续按原岗位核验。')])
body='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>V13 物流系统 · 演练验收记录</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6f5;color:#183f37;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1100px;margin:auto;padding:48px 24px}header{border-bottom:2px solid #16775b;padding-bottom:24px}small{letter-spacing:2px;color:#637d73}h1{font-size:36px;line-height:1.3}a{color:#0b7958}nav a{display:inline-block;background:#13694f;color:white;padding:10px 18px;border-radius:6px;text-decoration:none}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:28px 0}.card{background:white;border:1px solid #dce6e0;padding:20px}.card b{display:block;font-size:34px;line-height:1.4}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;padding:16px;border-bottom:1px solid #e1e8e4;vertical-align:top}th{width:160px}section{margin-top:30px}.note{border-left:4px solid #bf8e30;padding:16px 20px;background:#fff9ec}footer{font-size:13px;color:#64796f;margin-top:36px}@media(max-width:600px){main{padding:24px 16px}h1{font-size:27px}.cards{grid-template-columns:repeat(2,1fr)}th{width:100px}}</style><main><header><small>HAHA VENDING / V13 · 2026-11-02</small><h1>物流系统演练验收记录</h1><p>由实际业务入口产生的合成演练结果。分享页面从待排快照开始，下面的终态数字来自独立验收库。</p><nav><a href="../?dataset=sim200#map">打开 200 票地图工作台</a></nav></header><div class="cards">'''
body+=''.join(f'<div class="card"><b>{n}</b>{label}</div>' for n,label in cards)+'</div><table>'+''.join(f'<tr><th>{e(a)}</th><td>{e(b)}</td></tr>' for a,b in rows)+'</table>'
body+='''<section class="note"><b>使用范围</b><p>所有客户、仓站、报价、设备和授权材料均为 SIM 合成测试资料。地图坐标和仓口核验不能作为真实客户事实。每位访客使用独立浏览器数据库；关闭浏览器后数据留在该设备，不是多人共享的正式员工库。</p><p>公开页面使用浏览器可运行的候选计算，Dallas 交互道路试排有 6 站上限。四城市真实路网和原生 CP-SAT 在本机验证，不随 GitHub Pages 运行。小范围图不支持跨城市或全国连续货车道路。其余完整方案验收项见下方逐项矩阵。</p></section><section><h2>可追溯资料</h2><ul><li><a href="https://github.com/cscpengyuyan/haha-logistics-dispatch/blob/main/docs/V13-RUN.md">本机启动与备份恢复</a></li><li><a href="https://github.com/cscpengyuyan/haha-logistics-dispatch/blob/main/docs/sim200/README.md">200票生成、导入、续跑及统计口径</a></li><li><a href="https://github.com/cscpengyuyan/haha-logistics-dispatch/blob/main/docs/V13-ACCEPTANCE-MATRIX.md">44项逐项验收矩阵与未完成项</a></li><li><a href="https://github.com/cscpengyuyan/haha-logistics-dispatch/blob/main/docs/sim200/acceptance/results.csv">200票逐票结果</a></li></ul></section><footer>业务证据、真实道路证据、优化验证和浏览器验证分开记录。源码审查基线 bd564c6e9c9b28c682cee8057b43ceba7cb9f62e。未将测试通过数量等同于全部生产能力验收。</footer></main></html>'''
(root/'v13/data/acceptance.html').write_text(body,encoding='utf8')
print('Wrote v13/data/acceptance.html from recorded results')
